script:
(function(){
const LATE = ["Finance, please approve", "Quote approved"];
const ask = (frm) => frappe.call({method: "eye.revise", args: {op: "info", name: frm.doc.name}}).then((r) => {
  const m = r.message || {};
  const rows = (m.rows || []).map((x) => ({pick: (m.rows.length === 1) ? 1 : 0, label: x.label, pr: x.pr, status: x.status,
    cost: format_currency(x.cost, m.currency)}));
  if (!rows.length) return frappe.msgprint(__("This deal has no Cost Sheets yet."));
  const d = new frappe.ui.Dialog({
    title: __("Ask Production to revise"),
    size: "large",
    fields: [
      {fieldtype: "HTML", fieldname: "hint", options: `<div style="font-size:13px;color:var(--text-muted)">${frappe.utils.escape_html(frm.doc.customer_name || "")} · ${frappe.utils.escape_html(frm.doc.custom_deal_name || "")} · ${frm.doc.name}</div>`},
      {fieldtype: "Table", fieldname: "prs", label: __("Which Cost Sheets?"), cannot_add_rows: 1, cannot_delete_rows: 1, in_place_edit: 1, data: rows,
        fields: [
          {fieldtype: "Check", fieldname: "pick", label: __("Revise"), in_list_view: 1, columns: 1},
          {fieldtype: "Data", fieldname: "label", label: __("Line"), in_list_view: 1, read_only: 1, columns: 4},
          {fieldtype: "Data", fieldname: "pr", label: __("Request"), in_list_view: 1, read_only: 1, columns: 2},
          {fieldtype: "Data", fieldname: "status", label: __("Status"), in_list_view: 1, read_only: 1, columns: 1},
          {fieldtype: "Data", fieldname: "cost", label: __("Cost"), in_list_view: 1, read_only: 1, columns: 2},
        ]},
      {fieldtype: "Small Text", fieldname: "note", label: __("What should change?"), reqd: 1},
      {fieldtype: "Date", fieldname: "needed_by", label: __("Needed by")},
      {fieldtype: "HTML", fieldname: "warn", options: `<div style="font-size:12px;color:var(--text-muted)">${__("The deal can't move forward until Production sends the new Cost Sheet.")}</div>`},
    ],
    primary_action_label: __("Send to Production"),
    primary_action(v) {
      const picked = (d.fields_dict.prs.df.data || []).filter((x) => x.pick).map((x) => x.pr);
      if (!picked.length) return frappe.msgprint(__("Pick at least one Cost Sheet."));
      frappe.call({method: "eye.revise", args: {op: "send", name: frm.doc.name, prs: JSON.stringify(picked), note: v.note, needed_by: v.needed_by || ""},
        freeze: true, freeze_message: __("Sending to Production...")}).then(() => {
        d.hide();
        frappe.show_alert({message: __("Sent to Production"), indicator: "green"});
        frm.reload_doc();
      });
    }
  });
  d.show();
});
window.eye_ask_revision = ask;
const add = (frm) => {
  if (!frm || frm.doctype !== "Opportunity" || frm.is_new()) return;
  const $p = $(frm.wrapper).find(".eye-sum .eye-sum-pl");
  if (!$p.length || $p.find(".eye-ask-rev").length) return;
  if (LATE.includes(frm.doc.sales_stage) || frm.doc.custom_pricing_status !== "Priced") return;
  const $b = $('<button class="btn btn-xs btn-default eye-ask-rev" style="margin-top:8px;display:block">' + __("Ask Production to revise") + '</button>');
  $b.on("click", () => ask(frm));
  $p.append($b);
};
let t = null;
frappe.ui.form.on("Opportunity", {
  refresh(frm) {
    setTimeout(() => add(frm), 400);
    if (!frm.__eye_rev_obs) {
      frm.__eye_rev_obs = new MutationObserver(() => { clearTimeout(t); t = setTimeout(() => add(frm), 150); });
      frm.__eye_rev_obs.observe(frm.wrapper, {childList: true, subtree: true});
    }
  }
});
})();

(function(){
const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
const money = (v, c) => format_currency(flt(v), c);
const day = (d) => (d ? moment(d).format("D MMM YYYY") : "");
const pill = (s, tone) => `<span class="eye-dd-pill ${tone || "gray"}">${esc(__(s))}</span>`;
const ST = (d) => (d === 2 ? ["Cancelled", "red"] : d === 1 ? ["Submitted", "green"] : ["Draft", "gray"]);
const ICON = {
  pl: '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>',
  dl: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><path d="M12 4v11M7 10l5 5 5-5M5 20h14"/></svg>',
  upd: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 12a8 8 0 0 1 14-5.3M20 12a8 8 0 0 1-14 5.3"/><path d="M18 3v4h-4M6 21v-4h4"/></svg>',
};
const pdf = (name) => window.open(frappe.urllib.get_full_url("/api/method/frappe.utils.print_format.download_pdf?" + $.param({doctype: "Deal PL", name})));
const draw = (frm) => {
  if (frm.is_new()) return;
  frappe.call({method: "eye.pl", args: {op: "status", name: frm.doc.name}}).then((r) => {
    const s = r.message || {};
    const f = frm.fields_dict.custom_default_margin;
    const $sec = f ? $(f.wrapper).closest(".form-section") : null;
    if (!$sec || !$sec.length) return;
    $sec.parent().find(".eye-pl-doc").remove();
    const pl = s.pl, q = s.quote, p = s.proposal;
    if (!pl) return;
    const cur = pl.currency;
    const q_old = q && q.custom_pl && q.custom_pl !== pl.name;
    const p_old = p && p.pl && p.pl !== pl.name;
    let warn = "", main = `<button class="eye-dd-btn main" data-act="edit">${ICON.upd} ${__("Edit P&L")}</button>`;
    if (s.outdated) { warn = __("Costs changed after this P&L."); main = `<button class="eye-dd-btn main" data-act="rev">${ICON.upd} ${__("Update P&L")}</button>`; }
    else if (q_old) { warn = __("Quotation {0} is built on an older P&L.", [q.name]); main = `<button class="eye-dd-btn main" data-act="uq">${ICON.upd} ${__("Update Quotation")}</button>`; }
    else if (p_old) { warn = __("Proposal {0} is built on an older P&L.", [p.name]); main = `<button class="eye-dd-btn main" data-act="up">${ICON.upd} ${__("Update Proposal")}</button>`; }
    const st = ST(pl.docstatus);
    const meta = [day(pl.modified), pl.reason, pl.based_on ? __("based on {0}", [pl.based_on]) : ""].filter(Boolean).join(" · ");
    let html = `<div class="eye-dd-hero" style="--acc:#0f766e">
      <div class="eye-dd-top"><div class="eye-dd-icon">${ICON.pl}</div>
        <div class="eye-dd-who"><div class="eye-dd-kick">${__("Current P&L")}</div>
          <div class="eye-dd-name"><a href="/app/deal-pl/${encodeURIComponent(pl.name)}">${esc(pl.name)}</a>${pill(st[0], st[1])}${pill("Rev " + (pl.revision || 1), "violet")}${s.outdated ? pill("Outdated", "orange") : ""}</div>
          <div class="eye-dd-meta">${esc(meta)}</div></div>
        <div class="eye-dd-amt"><div class="k">${__("Selling")}</div><div class="v">${money(pl.total_selling, cur)}</div>
          <div class="s">${__("Cost")} ${money(pl.total_cost, cur)} · ${__("Margin")} ${Math.round(flt(pl.margin_pct) * 10) / 10}%</div></div></div>
      ${warn ? `<div class="eye-dd-chips"><span class="eye-dd-pill orange">${esc(warn)}</span></div>` : ""}
      <div class="eye-dd-acts">
        <button class="eye-dd-btn blue" data-dl="${esc(pl.name)}">${ICON.dl} ${__("Download PDF")}</button>
        <a class="eye-dd-btn" href="/app/deal-pl/${encodeURIComponent(pl.name)}">${__("Open")}</a>
        ${main}</div></div>`;
    const rows = s.history || [];
    if (rows.length) {
      html += `<div class="eye-dd-hist"><div class="k">${__("History")}</div>${rows.map((h) => { const t = ST(h.docstatus); return `<div class="eye-dd-row">
        <span class="dot"></span>
        <div class="n"><a href="/app/deal-pl/${encodeURIComponent(h.name)}">${esc(h.name)}</a>${pill(t[0], t[1])}<small>${h.name === pl.name ? __("Current") + " · " : ""}Rev ${h.revision || 1}${h.reason ? " · " + esc(h.reason) : ""}</small></div>
        <div class="d">${esc(day(h.modified))}</div>
        <div class="a ${h.docstatus === 1 ? "live" : ""}">${money(h.total_selling, cur)}</div>
        <button class="eye-dd-ic" data-dl="${esc(h.name)}" aria-label="${esc(__("Download {0}", [h.name]))}">${ICON.dl}</button></div>`; }).join("")}</div>`;
    }
    const $b = $(`<div class="eye-pl-doc" style="border:1px solid var(--border-color);border-radius:var(--border-radius-lg,12px);background:var(--card-bg,var(--fg-color));padding:20px 24px;margin:0 0 16px"><div class="eye-dd">${html}</div></div>`);
    $sec.before($b);
    $b.find("[data-dl]").on("click", function () { pdf(this.dataset.dl); });
    const ctx = {name: frm.doc.name, refresh: () => frm.reload_doc()};
    $b.find("[data-act]").on("click", function () {
      const a = this.dataset.act, X = window.nx_actions || {};
      if (a === "rev") return frappe.call({method: "eye.pl", args: {op: "revise", name: frm.doc.name}, freeze: true}).then(() => frm.reload_doc());
      if (a === "uq" && X.update_quotation) return X.update_quotation(ctx);
      if (a === "up" && X.create_proposal) return X.create_proposal(ctx);
      if (a === "edit" && X.create_pl) return X.create_pl(ctx);
    });
  });
};
frappe.ui.form.on("Opportunity", { refresh: draw, after_save: draw });
})();

(function(){
if (window.__eye_waits) return; window.__eye_waits = 1;
const RX = /^CRM-OPP-\d{4}-\d+$/;
const T = {
  orange: ["#fde8dc", "#7c2309", "#c2410c"], amber: ["#fdf3e1", "#6b3a00", "#b45309"],
  blue: ["#e6eefc", "#1e3a8a", "#1d4ed8"], green: ["#dcf3e4", "#14532d", "#15803d"],
  red: ["#fde2e2", "#991b1b", "#b91c1c"], gray: ["#eef0f3", "#3d4250", "#3d4250"]
};
const esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
let cache = {}, at = 0, busy = false, timer = null;
let eye_dragging = false, eye_drag_t = null;
const eye_is_dragging = () => eye_dragging || !!document.querySelector(".sortable-chosen, .sortable-ghost, .sortable-fallback, .sortable-drag, .dragging, .is-dragging, .kanban-card.dragging");
document.addEventListener("dragstart", () => { eye_dragging = true; }, true);
document.addEventListener("dragend", () => { clearTimeout(eye_drag_t); eye_drag_t = setTimeout(() => { eye_dragging = false; clearTimeout(timer); timer = setTimeout(run, 300); }, 900); }, true);
document.addEventListener("pointerup", () => { if (!eye_dragging) return; clearTimeout(eye_drag_t); eye_drag_t = setTimeout(() => { eye_dragging = false; clearTimeout(timer); timer = setTimeout(run, 300); }, 900); }, true);
const refresh_waits = () => { at = 0; clearTimeout(timer); timer = setTimeout(run, 900); };
$(document).on("ajaxComplete", (e, xhr, o) => {
  const pm = window.__eye_pending_move;
  if (!pm || !pm.name || !pm.to || !xhr || xhr.status !== 200) return;
  const s = String((o && o.url) || "") + " " + String(o && typeof o.data === "string" ? o.data : "");
  if (!/frappe\.client\.save/.test(s) || s.indexOf(pm.name) < 0) return;
  window.__eye_pending_move = null;
  setTimeout(() => {
    frappe.show_alert({message: __("P&L saved, moving to {0}...", [pm.to]), indicator: "blue"});
    if (window.nx_move) window.nx_move("Opportunity", [pm.name], "sales_stage", pm.to, false, false);
  }, 700);
});
$(document).on("ajaxComplete", (e, xhr, o) => {
  const s = String((o && o.url) || "") + " " + String(o && typeof o.data === "string" ? o.data : "");
  if (/deal_waits/.test(s)) return;
  if (/frappe\.client\.save|savedocs|set_value|eye\.|nexlify_board|cancel|submit/.test(s)) refresh_waits();
});
if (frappe.realtime && frappe.realtime.on) frappe.realtime.on("list_update", (d) => { if (d && d.doctype === "Opportunity") refresh_waits(); });

const find_cards = () => {
  const root = document.querySelector(".page-container:not([style*='none'])") || document.body;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const hits = [];
  let t;
  while ((t = w.nextNode())) {
    const v = (t.nodeValue || "").trim();
    if (!RX.test(v) || !t.parentElement || t.parentElement.closest("[data-eye-w], [data-eye-dn], .modal")) continue;
    t.parentElement.setAttribute("data-eye-num", v);
    hits.push([v, t.parentElement]);
  }
  const out = [];
  hits.forEach(([v, el]) => {
    let card = el;
    while (card.parentElement && card.parentElement !== root && card.parentElement.querySelectorAll("[data-eye-num]").length <= 1) {
      if (card.getAttribute("draggable") === "true") break;
      card = card.parentElement;
    }
    if (!card.closest(".sortable-ghost, .sortable-fallback, .sortable-drag, .sortable-chosen")) out.push([v, card]);
  });
  return out;
};
const next_box = (card) => {
  for (const b of card.querySelectorAll("button, a, div, span")) {
    if (b.closest("[data-eye-w]") || (b.textContent || "").trim().toLowerCase() !== "open") continue;
    let p = b.parentElement;
    while (p && p !== card) { if (/next step/i.test(p.textContent || "")) return p; p = p.parentElement; }
  }
  let best = null;
  card.querySelectorAll("div").forEach((d) => { if (!d.closest("[data-eye-w]") && /next step/i.test(d.textContent || "") && (!best || best.contains(d))) best = d; });
  return best && best !== card ? best.parentElement : null;
};
const act = (name, it) => {
  if (it.action === "pl" && window.nx_actions && window.nx_actions.create_pl) return window.nx_actions.create_pl({name});
  if (it.action === "uq" && window.nx_actions && window.nx_actions.update_quotation) return window.nx_actions.update_quotation({name});
  if (it.action === "pl_rev") return frappe.call({method: "eye.pl", args: {op: "revise", name}, freeze: true}).then(() => { frappe.show_alert({message: __("P&L updated"), indicator: "green"}); });
  if (it.route) return frappe.set_route(...it.route);
};
const eye_open = (() => { try { return new Set(JSON.parse(localStorage.getItem("eye_card_open") || "[]")); } catch (e) { return new Set(); } })();
const eye_save_open = () => { try { localStorage.setItem("eye_card_open", JSON.stringify([...eye_open])); } catch (e) {} };
const render = (name, card, data) => {
  const sig = JSON.stringify(data) + (eye_open.has(name) ? "1" : "0");
  if (card.dataset.eyeSig === sig && card.querySelector("[data-eye-w]")) return;
  card.dataset.eyeSig = sig;
  // undo the previous pass
  const old = card.querySelector("[data-eye-w]");
  const ph = card.querySelector("[data-eye-ph]");
  const moved = old && old.querySelector("[data-eye-nb]");
  if (moved && ph) ph.parentElement.insertBefore(moved, ph);
  card.querySelectorAll("[data-eye-hid]").forEach((e) => { e.style.display = ""; e.removeAttribute("data-eye-hid"); });
  card.querySelectorAll("[data-eye-w], [data-eye-dn], [data-eye-ph]").forEach((e) => e.remove());
  // deal name under the number
  if (data.deal && data.deal.indexOf(name) < 0) {
    const w2 = document.createTreeWalker(card, NodeFilter.SHOW_TEXT);
    let tn;
    while ((tn = w2.nextNode())) {
      if ((tn.nodeValue || "").trim() === name) {
        const dn = document.createElement("div");
        dn.setAttribute("data-eye-dn", "1");
        dn.textContent = data.deal;
        dn.style.cssText = "font-size:13px;font-weight:600;color:#2563eb;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis";
        tn.parentElement.insertAdjacentElement("afterend", dn);
        break;
      }
    }
  }
  const nb = next_box(card);
  const wrap = document.createElement("div");
  wrap.setAttribute("data-eye-w", "1");
  wrap.style.cssText = "display:flex;flex-direction:column;gap:6px;margin:6px 0";
  const holder = document.createElement("span");
  holder.setAttribute("data-eye-ph", "1");
  holder.style.display = "none";
  if (nb && nb.parentElement && nb.parentElement !== document.body) {
    nb.parentElement.insertBefore(holder, nb);
    nb.parentElement.insertBefore(wrap, nb);
  } else {
    card.appendChild(wrap);
  }
  // 1) two halves: Next step | Your action
  if (nb || data.box) {
    const grid = document.createElement("div");
    grid.style.cssText = (nb && data.box) ? "display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;align-items:stretch" : "display:block";
    if (nb) {
      nb.setAttribute("data-eye-nb", "1");
      nb.style.setProperty("margin", "0", "important");
      nb.style.setProperty("padding", "8px 10px", "important");
      nb.style.setProperty("display", "flex", "important");
      nb.style.setProperty("flex-direction", "column", "important");
      nb.style.setProperty("justify-content", "space-between", "important");
      nb.style.setProperty("gap", "6px", "important");
      if (data.box) {
        nb.title = (nb.textContent || "").replace(/\s+/g, " ").trim();
        Array.from(nb.children).forEach((ch, i) => { if (i > 0 && ch.tagName !== "BUTTON" && !ch.querySelector("button")) { ch.setAttribute("data-eye-hid", "1"); ch.style.display = "none"; } });
      }
      nb.querySelectorAll("button").forEach((b) => ["height:28px", "min-height:28px", "font-size:11.5px", "padding:0 4px", "width:100%", "margin:0", "white-space:nowrap", "overflow:hidden", "text-overflow:clip", "letter-spacing:-.1px", "line-height:28px"]
        .forEach((kv) => { const [k, v] = kv.split(":"); b.style.setProperty(k, v, "important"); }));
      grid.appendChild(nb);
    }
    if (data.box) {
      const b = data.box, c = T[b.tone] || T.gray;
      const cell = document.createElement("div");
      cell.setAttribute("data-eye-i", "box");
      cell.title = [b.label, b.text, b.sub].filter(Boolean).join(" · ");
      cell.style.cssText = `border-radius:10px;padding:8px 10px;background:${c[0]};color:${c[1]};display:flex;flex-direction:column;justify-content:space-between;gap:6px;cursor:pointer;min-width:0`;
      cell.innerHTML = `<div style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase">${esc(b.label)}${b.age ? " · " + esc(b.age) : ""}</div>
        <button data-eye-i="box" style="height:28px;width:100%;border:0;border-radius:7px;background:${c[2]};color:#fff;font-size:11.5px;font-weight:600;padding:0 4px;letter-spacing:-.1px;white-space:nowrap;overflow:hidden;text-overflow:clip;cursor:pointer">${esc(b.btn || __("Open"))}</button>`;
      grid.appendChild(cell);
    }
    wrap.appendChild(grid);
  }
  // 2) details: other waits + PO + the rest of the card, collapsible
  const extra = [];
  if (nb) {
    let s = wrap.nextElementSibling;
    const last = wrap.parentElement.lastElementChild;
    while (s && s !== last) { if (!s.hasAttribute("data-eye-ph")) extra.push(s); s = s.nextElementSibling; }
  }
  let dh = "";
  (data.more || []).forEach((m, i) => {
    const c = T[m.tone] || T.gray;
    dh += `<div data-eye-i="${i}" title="${esc([m.label, m.sub].filter(Boolean).join(" · "))}" style="display:flex;align-items:center;gap:8px;padding:5px 9px;border-radius:8px;background:${c[0]};color:${c[1]};cursor:pointer;font-size:12px">
      <span style="width:7px;height:7px;border-radius:50%;background:${c[2]};flex:none"></span>
      <div style="flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><b>${esc(m.text)}</b>${m.age ? " · " + esc(m.age) : ""}</div></div>`;
  });
  if (data.po) {
    const c = T[data.po.tone] || T.gray;
    dh += `<div style="display:flex;align-items:center;gap:8px;padding:0 2px;font-size:12px">
      <div style="flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><b>PO</b> · ${esc(data.po.text)}</div>
      <span style="font-size:11px;font-weight:600;padding:1px 7px;border-radius:999px;background:${c[0]};color:${c[1]}">${esc(data.po.tag)}</span></div>`;
  }
  if (dh || extra.length) {
    const open = eye_open.has(name);
    const n = (data.more || []).length;
    const tog = document.createElement("div");
    tog.setAttribute("data-eye-tog", "1");
    tog.style.cssText = "display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-muted);cursor:pointer;padding:0 2px;user-select:none";
    tog.innerHTML = `<span style="display:inline-block;transition:transform .15s;transform:rotate(${open ? 90 : 0}deg)">›</span><span>${open ? __("Hide details") : __("Details")}</span>`
      + (!open && n ? `<span style="margin-left:auto;font-weight:600;color:${(T[data.more[0].tone] || T.gray)[2]}">+${n} ${__("waiting")}</span>` : "")
      + (!open && !n && data.po ? `<span style="margin-left:auto">PO · ${esc(data.po.tag)}</span>` : "");
    wrap.appendChild(tog);
    const det = document.createElement("div");
    det.style.cssText = "display:" + (open ? "flex" : "none") + ";flex-direction:column;gap:6px";
    det.innerHTML = dh;
    wrap.appendChild(det);
    if (!open) extra.forEach((e) => { e.setAttribute("data-eye-hid", "1"); e.style.display = "none"; });
  }
  wrap.addEventListener("click", (e) => {
    if (e.target.closest("[data-eye-nb]")) return;
    e.stopPropagation(); e.preventDefault();
    if (e.target.closest("[data-eye-tog]")) {
      if (eye_open.has(name)) eye_open.delete(name); else eye_open.add(name);
      eye_save_open();
      card.dataset.eyeSig = "";
      return render(name, card, data);
    }
    const t = e.target.closest("[data-eye-i]");
    if (!t) return;
    const k = t.getAttribute("data-eye-i");
    act(name, k === "box" ? data.box : data.more[+k]);
  }, true);
  ["mousedown", "pointerdown", "dragstart"].forEach((ev) => wrap.addEventListener(ev, (e) => { if (!e.target.closest("[data-eye-nb]")) e.stopPropagation(); }));
};
const run = () => {
  const r = frappe.get_route();
  if (r[0] !== "List" || r[1] !== "Opportunity") return;
