(function(){
const CH = "Opportunity Costing";
const r2 = v => Math.round(flt(v) * 100) / 100;
frappe.ui.form.on(CH, {
  margin(frm, cdt, cdn) {
    const r = locals[cdt][cdn];
    if (r.__eye_busy) return;
    const c = flt(r.cost); if (!(c > 0)) return;
    r.__eye_busy = 1;
    const s = flt(r.margin) > 0 ? r2(c * (1 + flt(r.margin) / 100)) : 0;
    Promise.resolve(frappe.model.set_value(cdt, cdn, "selling", s)).then(() => { r.__eye_busy = 0; });
  },
  selling(frm, cdt, cdn) {
    const r = locals[cdt][cdn];
    if (r.__eye_busy) return;
    const c = flt(r.cost); if (!(c > 0) || !(flt(r.selling) > 0)) return;
    r.__eye_busy = 1;
    const m = r2((flt(r.selling) / c - 1) * 100);
    Promise.resolve(frappe.model.set_value(cdt, cdn, "margin", m)).then(() => { r.__eye_busy = 0; });
  }
});
})();

