async function proposals(frm) {
	const f = frm.fields_dict.custom_proposal_view;
	if (!f) return;
	if (frm.is_new()) return f.$wrapper.html("");
	const list = await frappe.db.get_list("Proposal", { filters: { opportunity: frm.doc.name },
		fields: ["name", "proposal_date", "valid_till", "proposal_type", "status", "total", "grand_total", "currency", "prepared_by_name", "revision_of", "creation"],
		order_by: "creation desc", limit: 50 });
	const live = list.filter((p) => !["Superseded", "Rejected"].includes(p.status));
	const base = live.find((p) => (p.proposal_type || "Full") === "Full") || live[live.length - 1];
	const set = base ? live.filter((p) => p === base || (p.proposal_type === "Changes only" && p.creation > base.creation)).reverse() : [];
	let html = now_line(frm);
	if (!base) html += empty(__("No current proposal"), list.length ? __("Create a new Proposal") : __("Create Proposal"));
	else {
		const total = set.reduce((a, p) => a + flt(p.grand_total), 0), before = set.reduce((a, p) => a + flt(p.total), 0);
		const meta = [day(base.proposal_date), base.valid_till ? __("valid till {0}", [day(base.valid_till)]) : "",
			base.prepared_by_name ? __("prepared by {0}", [base.prepared_by_name]) : ""].filter(Boolean).join(" · ");
		let inside = "";
		if (set.length > 1) inside = effect(set.map((p) => ({ name: p.name, type: p.proposal_type || "Full", status: p.status, date: p.proposal_date, amount: p.grand_total, currency: p.currency })), "proposal");
		else inside = chips(((await frappe.db.get_doc("Proposal", base.name)).items || []).filter((r) => !r.hide_in_proposal), base.currency);
		html += `<div class="eye-dd-hero">
			<div class="eye-dd-top"><div class="eye-dd-icon">${ICON.doc}</div>
				<div class="eye-dd-who"><div class="eye-dd-kick">${__("Current proposal")}</div>
					<div class="eye-dd-name"><a href="/app/proposal/${encodeURIComponent(base.name)}">${esc(base.name)}</a>${pill(base.status)}${set.length > 1 ? pill(__("+{0} change(s)", [set.length - 1]), "violet") : pill(base.proposal_type || "Full", "violet")}</div>
					<div class="eye-dd-meta">${esc(meta)}</div></div>
				<div class="eye-dd-amt"><div class="k">${set.length > 1 ? __("Total of {0} proposals incl. tax", [set.length]) : __("Total incl. tax")}</div><div class="v">${money(total, base.currency)}</div>
					<div class="s">${money(before, base.currency)} ${__("before tax")}</div></div></div>
			${inside}
			<div class="eye-dd-acts">
				<button class="eye-dd-btn blue" data-dl="${esc(base.name)}">${ICON.dl} ${__("Download PDF")}</button>
				<a class="eye-dd-btn" href="/app/proposal/${encodeURIComponent(base.name)}">${__("Open")}</a>
				${base.status === "Draft" ? `<button class="eye-dd-btn" data-sent="${esc(base.name)}">${__("Mark as sent")}</button>` : ""}
				<button class="eye-dd-btn main" data-upd>${ICON.upd} ${__("Update Proposal")}</button></div></div>`;
	}
	html += hist(list.map((p) => ({ route: "proposal", name: p.name, status: p.status, date: p.proposal_date,
		amount: p.grand_total, currency: p.currency, live: !["Superseded", "Rejected"].includes(p.status),
		sub: (set.includes(p) ? __("Current") + " · " : "") + __(p.proposal_type || "Full") + (p.revision_of ? " · " + __("after {0}", [p.revision_of]) : "") })));
	f.$wrapper.html(`<div class="eye-dd">${html}</div>`);
	f.$wrapper.find("[data-dl]").on("click", function () { pdf("Proposal", this.dataset.dl, "Eye Proposal", true); });
	f.$wrapper.find("[data-upd]").on("click", act(frm, "create_proposal"));
	f.$wrapper.find("[data-sent]").on("click", async function () {
		await frappe.db.set_value("Proposal", this.dataset.sent, "status", "Sent");
		frappe.show_alert({ message: __("Marked as sent"), indicator: "green" });
		proposals(frm);
	});
}

