const esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
const money = (v, c) => format_currency(flt(v), c);
const tone = (s) => {
	const t = (s || "").toLowerCase();
	return /cancel|reject/.test(t) ? "red" : /priced|complete|sent|done|approved/.test(t) ? "green" : /pend|progress|request|wait|open|question/.test(t) ? "orange" : "gray";
