const pill = (s) => (s ? `<span class="indicator-pill ${tone(s)}">${esc(__(s))}</span>` : "");

function sheet(doc, ccy, open) {
	const costs = doc.costs || [];
	const used = new Set();
	const curs = [...new Set(costs.map((c) => c.custom_currency || ccy))];
	const line = (c) => {
		const rc = c.custom_currency || ccy;
		const base = c.custom_base_amount != null ? flt(c.custom_base_amount) : flt(c.amount) * (flt(c.custom_exchange_rate) || 1);
		const desc = c.description && c.description !== c.item_code ? `<div class="eye-cs-sub">${esc(c.description)}</div>` : "";
		const notes = c.notes ? `<div class="eye-cs-sub">${esc(c.notes)}</div>` : "";
		return { base, html: `<tr>
			<td><div class="eye-cs-el">${esc(c.item_code || c.description || "—")}</div>${desc}${notes}</td>
			<td>${esc(c.supplier || "—")}</td>
			<td class="num">${esc(flt(c.qty))}${c.uom && c.uom !== "Nos" ? " " + esc(c.uom) : ""}</td>
			<td class="num">${money(c.rate, rc)}</td>
			<td class="num">${money(c.amount, rc)}</td>
			<td class="num muted">${rc === ccy ? "—" : esc(flt(c.custom_exchange_rate, 4))}</td>
			<td class="num strong">${money(base, ccy)}</td></tr>` };
	};
	const head = `<thead><tr><th>${__("Cost element")}</th><th>${__("Supplier")}</th><th class="num">${__("Qty")}</th>
		<th class="num">${__("Unit cost")}</th><th class="num">${__("Amount")}</th><th class="num">${__("Rate")}</th>
		<th class="num">${__("Amount")} (${esc(ccy)})</th></tr></thead>`;
	const block = (title, sub, qty, lines, total) => `<div class="eye-cs-req">
		<div class="eye-cs-reqhead">
			<div><span class="eye-cs-reqname">${esc(title)}</span>${qty ? `<span class="eye-cs-qty">× ${esc(qty)}</span>` : ""}
				${sub ? `<div class="eye-cs-sub">${esc(sub)}</div>` : ""}</div>
			<div class="eye-cs-reqtotal">${money(total, ccy)}</div></div>
		${lines.length ? `<div class="table-responsive"><table class="eye-cs-table">${head}<tbody>${lines.map((l) => l.html).join("")}</tbody></table></div>`
			: `<div class="eye-cs-empty">${__("No cost elements yet")}</div>`}</div>`;
	let body = "", sum = 0;
	(doc.items || []).forEach((it) => {
		const mine = costs.filter((c) => c.sales_item_row && c.sales_item_row === it.requirement);
		mine.forEach((c) => used.add(c.name));
		const lines = mine.map(line);
		const total = lines.length ? lines.reduce((a, l) => a + l.base, 0) : flt(it.cost);
		sum += total;
		body += block(it.custom_sales_item || it.description, it.description !== it.custom_sales_item ? it.description : "", flt(it.qty), lines, total);
	});
	const rest = costs.filter((c) => !used.has(c.name)).map(line);
	if (rest.length) {
		const t = rest.reduce((a, l) => a + l.base, 0); sum += t;
		body += block(__("Other costs"), "", 0, rest, t);
	}
	const total = flt(doc.total_cost) || sum;
	const facts = [
		doc.required_by && [__("Required by"), frappe.datetime.str_to_user(doc.required_by)],
		doc.priced_on && [__("Priced on"), frappe.datetime.str_to_user(doc.priced_on)],
		curs.length && [__("Cost currency"), curs.join(", ")],
	].filter(Boolean).map((f) => `<div class="eye-cs-fact"><span>${f[0]}</span><b>${esc(f[1])}</b></div>`).join("");
	const notes = [
		[__("Notes from Sales"), doc.sales_notes], [__("Notes for Sales"), doc.custom_production_notes],
		[__("Question from Production"), doc.production_question], [__("Reply from Sales"), doc.sales_reply],
	].filter((n) => n[1] && strip_html(n[1]).trim())
		.map((n) => `<div class="eye-cs-note"><span>${n[0]}</span>${esc(strip_html(n[1]))}</div>`).join("");
	return { total, html: `<details class="eye-cs-sheet" ${open ? "open" : ""}>
		<summary class="eye-cs-head">
			<span class="eye-cs-caret">›</span>
			<a href="/app/pricing-request/${encodeURIComponent(doc.name)}" class="eye-cs-name" onclick="event.stopPropagation()">${esc(doc.name)}</a>
			${pill(doc.status)}${doc.pending_change ? `<span class="indicator-pill orange">${__("Change pending")}</span>` : ""}
			<span class="eye-cs-headtotal">${money(total, ccy)}</span></summary>
		<div class="eye-cs-inner">
			${facts ? `<div class="eye-cs-facts">${facts}</div>` : ""}
			${notes}
			${body || `<div class="eye-cs-empty">${__("Nothing requested on this Cost Sheet.")}</div>`}
		</div></details>` };
}

