		const eye_short = (v, c) => (Math.abs(flt(v)) < 10000 ? format_currency(flt(v), c, 0)
			: `${get_currency_symbol(c) || c} ${new Intl.NumberFormat(undefined, { notation: "compact", maximumFractionDigits: 1 }).format(flt(v))}`);
		const eye_blue = "background:var(--blue-500,#2490ef) !important;border-color:var(--blue-500,#2490ef) !important;color:#fff !important;font-weight:600 !important";
		frm.__eye_prop_seg = lp
			? `<div class="eye-prop-seg"><div class="k">${__("Proposal")}</div>
				<div class="v"><a href="/app/proposal/${encodeURIComponent(lp.name)}">${esc(lp.name)}</a><span class="indicator-pill no-indicator-dot ${PILL[lp.status] || "gray"}">${esc(__(lp.status))}</span><button class="btn btn-xs pdf eye-prop-dl" data-name="${esc(lp.name)}" style="${eye_blue}">${frappe.utils.icon("download", "xs")} PDF</button></div></div>`
			: `<div class="eye-prop-seg"><div class="k">${__("Proposal")}</div><div class="v"><span class="text-muted">${__("Not made yet")}</span></div></div>`;
		const $sum = frm.$wrapper.find(".eye-sum");
		$sum.find(".eye-prop-seg").remove();
		const $q = $sum.find(".k").filter((i, el) => $(el).text().trim() === __("Quotation")).first().parent();
		if ($q.length) $q.before(frm.__eye_prop_seg);
		if (!window.__eye_prop_dl) {
			window.__eye_prop_dl = 1;
			$(document).on("click", ".eye-prop-dl", (e) => { e.preventDefault(); e.stopPropagation(); pdf($(e.currentTarget).data("name")); });
		}
	}
	frm.remove_custom_button(__("Download Proposal"));
	frm.remove_custom_button(__("Create Proposal"));
	const latest = r.proposals.find((p) => !["Superseded", "Rejected"].includes(p.status)) || r.proposals[0];
	if (latest) $();
	else if (r.full_count) $();
	const money = (v, c) => format_currency(v, c || r.currency);
	const rows = r.proposals.map((p) => `<tr class="${p.status === "Superseded" ? "text-muted" : ""}">
		<td><a href="/app/proposal/${encodeURIComponent(p.name)}"><b>${esc(p.name)}</b></a>${p.revision_of ? `<div class="small text-muted">${__("after")} ${esc(p.revision_of)}</div>` : ""}</td>
		<td>${esc(frappe.datetime.str_to_user(p.proposal_date))}</td>
		<td>${esc(__(p.proposal_type))}</td>
		<td><span class="indicator-pill ${PILL[p.status] || "gray"}">${esc(__(p.status))}</span></td>
		<td class="text-right">${money(p.total, p.currency)}</td>
		<td class="text-right"><b>${money(p.grand_total, p.currency)}</b></td>
		<td class="text-right"><button class="btn btn-xs btn-default eye-pr-dl" data-name="${esc(p.name)}">${frappe.utils.icon("printer", "xs")} PDF</button></td></tr>`).join("");
	const label = r.proposals.length ? __("Update Proposal") : __("Create Proposal");
	f.$wrapper.html(`
		<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
			<span class="text-muted small">${r.full_count ? __("Deal now: {0} item(s), {1}", [r.full_count, money(r.full_total)]) : __("No priced services yet")}</span>
			<button class="btn btn-sm btn-primary eye-pr-new" style="margin-left:auto">${label}</button>
		</div>
		${r.proposals.length ? `<div class="table-responsive"><table class="table table-sm" style="margin:0">
			<thead><tr class="text-muted small"><th>${__("Proposal")}</th><th>${__("Date")}</th><th>${__("Type")}</th><th>${__("Status")}</th>
			<th class="text-right">${__("Total")}</th><th class="text-right">${__("Incl. tax")}</th><th></th></tr></thead>
			<tbody>${rows}</tbody></table></div>` : `<div class="text-muted" style="padding:10px 0">${__("No proposal yet.")}</div>`}`);
	f.$wrapper.find(".eye-pr-new").on("click", () => eye_prop_go(frm));
	f.$wrapper.find(".eye-pr-dl").on("click", (e) => pdf($(e.currentTarget).data("name")));
}

window.eye_proposal = { start, render };
