frappe.ui.form.on("Opportunity", {
	refresh(frm) {
		const g = frm.fields_dict.custom_costing && frm.fields_dict.custom_costing.grid;
		if (!g) return;
		const rows = (frm.doc.custom_costing || []).filter((r) => r.custom_original_cost);
		const curs = [...new Set(rows.map((r) => r.custom_original_currency || "*"))];
		const same = curs.length === 1 && curs[0] === frm.doc.currency;
		g.update_docfield_property("custom_original_cost", "label",
			curs.length === 1 && curs[0] !== "*" ? __("Cost in {0}", [curs[0]]) : __("Original Cost"));
		g.update_docfield_property("custom_original_cost", "in_list_view", same || !rows.length ? 0 : 1);
		g.update_docfield_property("cost", "label", __("Cost in {0}", [frm.doc.currency || ""]));
		g.reset_grid();
	},
});

// Cost Currency on top is the currency of every cost line; a line can still be changed on its own afterwards.
const eye_cs_cur = (frm, row) => {
	frappe.model.set_value(row.doctype, row.name, "custom_currency", frm.doc.currency);
	frappe.model.set_value(row.doctype, row.name, "custom_exchange_rate", 0);
};
frappe.ui.form.on("Pricing Request", {
	currency(frm) {
		if (!frm.doc.currency) return;
		const rows = (frm.doc.costs || []).filter((r) => r.custom_currency !== frm.doc.currency);
		rows.forEach((r) => eye_cs_cur(frm, r));
		frm.refresh_field("costs");
		if (rows.length) frappe.show_alert({ message: __("{0} cost line(s) now in {1}", [rows.length, frm.doc.currency]), indicator: "blue" });
	},
});
frappe.ui.form.on("Pricing Request Cost", {
	costs_add(frm, cdt, cdn) {
		if (frm.doc.currency) eye_cs_cur(frm, locals[cdt][cdn]);
	},
	custom_currency(frm, cdt, cdn) {
		frappe.model.set_value(cdt, cdn, "custom_exchange_rate", 0);
	},
});

(() => {
