(() => {
	// ERPNext's CRM activities move the form footer (comments + timeline) into "All Activities"
	// and hide the comment box; this puts it back under the form like every other document
	const back = (frm) => {
		if (frm.is_new() || !frm.footer || !frm.footer.wrapper) return;
		const $foot = $(frm.footer.wrapper);
		const $home = frm.footer.parent ? $(frm.footer.parent) : null;
		if ($home && $home.length && !$foot.parent().is($home)) $foot.appendTo($home);
		$foot.show();
		$foot.find(".comment-box").show();
		$foot.find(".timeline-actions .btn-default").show();
		if (frm.fields_dict.all_activities_section) frm.toggle_display("all_activities_section", false);
	};
	const run = (frm) => [0, 400, 1200].forEach((ms) => setTimeout(() => back(frm), ms));
	frappe.ui.form.on("Opportunity", { refresh: run, onload_post_render: run });
})();

(() => {
	window.nx_actions = window.nx_actions || {};
	const call = (op, args, opts) => frappe.call({ method: "eye.billing", args: { op, ...args }, ...(opts || {}) }).then((r) => r.message && r.message.result);
	const dialog = async (opportunity, after) => {
		const so = await call("so_lines", { opportunity });
		const cur = so.currency;
		const rows = so.rows.filter((r) => r.left > 0.000001 && flt(r.rate) > 0).map((r) => {
			const left_amount = flt(r.left * r.rate, 2);
			return { so_detail: r.so_detail, item_code: r.item_code, rate: r.rate, left_amount, amount: left_amount, total_amount: flt(r.qty * r.rate, 2), billed_amount: flt((r.qty - r.left) * r.rate, 2) };
		});
		if (!rows.length) return frappe.msgprint(__("Everything on Sales Order {0} is already requested.", [so.sales_order]));
		const starts = await frappe.db.get_list("Billing Stage", { filters: { custom_can_start_here: 1 },
			fields: ["name", "custom_start_default"], order_by: "creation asc", limit: 50 });
		const d = new frappe.ui.Dialog({
			title: __("Request an invoice"), size: "extra-large",
			fields: [
				{ fieldtype: "Select", fieldname: "stage", label: __("Stage"), reqd: 1, options: starts.map((x) => x.name),
					default: (starts.find((x) => x.custom_start_default) || starts[0] || {}).name, hidden: starts.length < 2 ? 1 : 0 },
				{ fieldtype: "Date", fieldname: "expected_date", label: __("Expected invoice date"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Finance") },
				{ fieldtype: "Section Break", label: __("Items from {0}", [so.sales_order]) },
				{ fieldtype: "Percent", fieldname: "pct", label: __("% of what's left"), onchange() {
					const p = flt(d.get_value("pct"));
					d.fields_dict.lines.df.data.forEach((r) => (r.amount = flt((r.left_amount * p) / 100, 2)));
					d.fields_dict.lines.grid.refresh();
				} },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Section Break" },
				{ fieldtype: "Table", fieldname: "lines", label: __("Lines"), cannot_add_rows: 1, in_place_edit: 1, data: rows, fields: [
					{ fieldtype: "Data", fieldname: "so_detail", hidden: 1 },
					{ fieldtype: "Float", fieldname: "rate", hidden: 1 },
					{ fieldtype: "Link", fieldname: "item_code", label: __("Item"), options: "Item", read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "total_amount", label: __("Line total"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "billed_amount", label: __("Already billed"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "left_amount", label: __("Left to bill"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "amount", label: __("Amount to bill"), options: cur, in_list_view: 1, columns: 2 },
				] },
			],
			primary_action_label: __("Request"),
			primary_action(v) {
				const lines = (d.fields_dict.lines.df.data || []).filter((r) => flt(r.amount) > 0);
				if (!lines.length) return frappe.msgprint(__("Enter the amount to bill on at least one line."));
				const over = lines.filter((r) => flt(r.amount) > flt(r.left_amount) + 0.005);
				if (over.length) return frappe.msgprint(over.map((r) => __("{0}: only {1} is left to bill",
					[frappe.utils.escape_html(r.item_code), format_currency(r.left_amount, cur)])).join("<br>"));
				const payload = lines.map((r) => ({ so_detail: r.so_detail, qty: Math.round((flt(r.amount) / flt(r.rate)) * 1e9) / 1e9 }));
				call("create", { opportunity, rows: JSON.stringify(payload), expected_date: v.expected_date, notes: v.notes, stage: v.stage },
					{ freeze: true }).then((name) => {
					d.hide();
					frappe.show_alert({ message: __("Invoice request {0}", [name]), indicator: "green" });
					after && after();
				});
			},
		});
		d.show();
	};
	window.nx_actions.request_invoice = (ctx) => {
		const go = () => dialog(ctx.name, ctx.refresh);
		frappe.db.get_value("Opportunity", ctx.name, "custom_sales_order").then((r) => {
			if (r.message && r.message.custom_sales_order) return go();
			frappe.msgprint(__("Invoices are requested once Accounts approve the project."));
		});
	};

	const eye_can_approve = () => frappe.session.user === "Administrator"
		|| frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
	const eye_approve = (name, done) => frappe.prompt(
		[{ fieldtype: "Small Text", fieldname: "note", label: __("Note (optional)") }],
		(v) => frappe.call({ method: "eye.pricing", args: { op: "approve_project", name, note: v.note || "" },
			freeze: true, freeze_message: __("Approving...") }).then(() => {
			frappe.show_alert({ message: __("Approved: the Sales Order is made"), indicator: "green" });
			done && done();
		}),
		__("Approve the project"), __("Approve"));
	const eye_reject = (name, done) => frappe.prompt(
		[{ fieldtype: "Small Text", fieldname: "reason", label: __("Reason"), reqd: 1 }],
		(v) => frappe.call({ method: "eye.pricing", args: { op: "reject_project", name, reason: v.reason },
			freeze: true }).then(() => {
			frappe.show_alert({ message: __("Sent back to Deals in Hand"), indicator: "orange" });
			done && done();
		}),
		__("Send back to Sales"), __("Reject"));
	window.nx_actions.approve_project = (ctx) => eye_approve(ctx.name, ctx.refresh);
	window.nx_actions.reject_project = (ctx) => eye_reject(ctx.name, ctx.refresh);

	window.nx_actions.create_pl = async (ctx) => {
		const doc = await frappe.db.get_doc("Opportunity", ctx.name);
		const reqs = doc.custom_requirements || [];
		const codes = [...new Set(reqs.map((r) => r.item_code).filter(Boolean))];
		const items = codes.length ? await frappe.db.get_list("Item", { filters: { name: ["in", codes] },
			fields: ["name", "item_group"], limit: codes.length }) : [];
		const group_of = Object.fromEntries(items.map((i) => [i.name, i.item_group]));
		const own_line = (r) => group_of[r.item_code] === "Service";
		const by_req = Object.fromEntries((doc.custom_costing || []).map((c) => [c.requirement, c]));
		const rows = [];
		reqs.forEach((r) => {
			const c = by_req[r.name];
			const own = own_line(r);
			if (!c && !own) return;
			const cost = flt(c ? c.cost : 0);
			rows.push({ row_id: c ? c.name : "", requirement: r.name, item: r.item_code, own, orig_cost: cost, original: (c && c.custom_original_cost) || "", ocur: (c && c.custom_original_currency) || "",
				source: own ? __("You") : __("Cost Sheet"),
				description: (c && c.description) || r.description || r.item_code, qty: (c && c.qty) || r.qty || 1,
				cost, margin: flt(c ? c.margin : 0), selling: flt(c ? c.selling : 0) });
		});
		const ocurs = [...new Set(rows.filter((r) => r.original).map((r) => r.ocur || "*"))];
		const same_cur = ocurs.length === 1 && ocurs[0] === doc.currency;
		const orig_label = ocurs.length === 1 && ocurs[0] !== "*" ? __("Cost in {0}", [ocurs[0]]) : __("Original Cost");
		if (!rows.length) return frappe.msgprint(__("Nothing to price yet: the lines that need Production are still with them."));
		const cur = doc.currency;
		rows.forEach((r) => (r.currency = cur));
		const money = (v) => format_currency(flt(v), cur);
		const calc = () => rows.forEach((r) => {
			if (!r.own) r.cost = r.orig_cost;
			const c = flt(r.cost);
			if (r._ls !== undefined && flt(r.selling) !== r._ls && c > 0) r.margin = flt((flt(r.selling) / c - 1) * 100, 2);
			else if (c > 0) r.selling = flt(r.margin) > 0 ? flt(c * (1 + flt(r.margin) / 100), 2) : 0;
			if (c <= 0) r.margin = flt(r.selling) > 0 ? 100 : 0;
			r._ls = flt(r.selling);
		});
		const tile = (k, v, tone) => `<div style="border:1px solid var(--border-color);border-radius:10px;padding:8px 12px">
			<div style="font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted)">${k}</div>
			<div style="font-size:16px;font-weight:600;margin-top:2px;${tone ? `color:${tone}` : ""}">${v}</div></div>`;
		let d;
		const summary = () => {
			calc();
			const cost = rows.reduce((s, r) => s + flt(r.cost), 0);
			const sell = rows.reduce((s, r) => s + flt(r.selling), 0);
			const m = sell - cost;
			const pct = sell ? (m / sell) * 100 : 0;
			const tone = m > 0 ? "var(--green-600, #2b7a3b)" : m < 0 ? "var(--red-500, #e03636)" : "";
			d.fields_dict.summary.$wrapper.html(`<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px">
				${tile(__("Total cost"), money(cost))}${tile(__("Selling"), money(sell))}
				${tile(__("Margin"), money(m), tone)}${tile(__("Margin %"), `${Math.round(pct * 10) / 10}%`, tone)}</div>`);
		};
		d = new frappe.ui.Dialog({
			title: __("P&L · {0}", [doc.customer_name || doc.name]),
			size: "extra-large",
			fields: [
				{ fieldtype: "Percent", fieldname: "all", label: __("Margin for all lines %"), default: doc.custom_default_margin,
					onchange() {
						if (!d.__eye_ready) return;
						const p = d.get_value("all");
						if (p === null || p === undefined || p === "") return;
						d.__eye_touched = 1;
						rows.forEach((r) => (r.margin = flt(p)));
						calc();
						d.fields_dict.lines.grid.refresh();
						summary();
					} },
				{ fieldtype: "Section Break" },
				{ fieldtype: "HTML", fieldname: "summary" },
				{ fieldtype: "Section Break", label: __("Lines"),
					description: __("Cost Sheet lines carry Production's cost. On your lines enter the cost and margin, or only the selling price when there is no cost") },
				{ fieldtype: "Table", fieldname: "lines", cannot_add_rows: 1, cannot_delete_rows: 1, in_place_edit: 1, data: rows,
					fields: [
						{ fieldtype: "Data", fieldname: "row_id", hidden: 1 },
						{ fieldtype: "Data", fieldname: "source", label: __("From"), read_only: 1, in_list_view: 1, columns: 1 },
						{ fieldtype: "Link", options: "Item", fieldname: "item", label: __("Item"), read_only: 1, in_list_view: 1, columns: 2 },
						{ fieldtype: "Data", fieldname: "description", label: __("Description"), read_only: 1, in_list_view: 1, columns: 1 },
						{ fieldtype: "Float", fieldname: "qty", label: __("Qty"), read_only: 1, in_list_view: 1, columns: 1 },
						{ fieldtype: "Data", fieldname: "original", label: orig_label, read_only: 1, in_list_view: same_cur ? 0 : 1, hidden: same_cur ? 1 : 0, columns: 1 },
						{ fieldtype: "Currency", fieldname: "cost", label: __("Cost in {0}", [cur]), options: "currency", in_list_view: 1, columns: 1 },
						{ fieldtype: "Percent", fieldname: "margin", label: __("Margin %"), in_list_view: 1, columns: 1 },
						{ fieldtype: "Currency", fieldname: "selling", label: __("Selling"), options: "currency", in_list_view: 1, columns: 1 },
					] },
			],
			primary_action_label: __("Save P&L"),
			primary_action() {
				calc();
				const missing = rows.filter((r) => flt(r.selling) <= 0);
				if (missing.length) {
					return frappe.msgprint(__("Enter a margin (or a selling price for services) for: {0}", [missing.map((r) => frappe.utils.escape_html(r.description)).join(", ")]));
				}
				const by_row = Object.fromEntries(rows.filter((r) => r.row_id).map((r) => [r.row_id, r]));
				doc.custom_costing = doc.custom_costing || [];
				doc.custom_costing.forEach((c) => {
					const r = by_row[c.name];
					if (!r) return;
					c.margin = flt(r.margin);
					c.selling = r.selling;
					if (r.own) c.cost = flt(r.cost);
				});
				rows.filter((r) => !r.row_id && r.own).forEach((r) => doc.custom_costing.push({
					doctype: "Opportunity Costing", parentfield: "custom_costing", parenttype: "Opportunity", parent: doc.name,
					requirement: r.requirement, description: r.description, qty: r.qty,
					cost: flt(r.cost), margin: flt(r.margin), selling: r.selling,
				}));
				if (d.__eye_touched && d.get_value("all") !== null && d.get_value("all") !== undefined) doc.custom_default_margin = flt(d.get_value("all"));
				frappe.call({ method: "frappe.client.save", args: { doc }, freeze: true, freeze_message: __("Saving the P&L...") })
					.then(() => {
						d.hide();
						frappe.show_alert({ message: __("P&L saved"), indicator: "green" });
						if (ctx.refresh) ctx.refresh();
					});
			},
		});
		d.show();
		summary();
		setTimeout(() => (d.__eye_ready = 1), 400);
		d.$wrapper.on("change", "input", () => setTimeout(() => {
			calc();
			d.fields_dict.lines.grid.refresh();
			summary();
		}, 50));
	};

	window.nx_actions.send_to_production = async (ctx) => {
		const doc = await frappe.db.get_doc("Opportunity", ctx.name);
		const d = new frappe.ui.Dialog({
			title: __("Send to Production"),
