			await frappe.xcall("nexlify_board.transition_rules.move", { doctype: "Opportunity", names: [ctx.name],
				field: "sales_stage", to: "Proposal", values: res });
			if (ctx.refresh) ctx.refresh();
		}
		const make = async (mode) => {
			const m = await frappe.call({ method: "eye.proposal", args: { action: "make", opportunity: ctx.name, mode },
				freeze: true, freeze_message: __("Making the proposal...") });
			frappe.show_alert({ message: __("Proposal {0} is ready", [`<a href="/app/proposal/${encodeURIComponent(m.message)}">${esc(m.message)}</a>`]), indicator: "green" }, 8);
			if (ctx.refresh) ctx.refresh();
		};
		const r = (await frappe.call({ method: "eye.proposal", args: { action: "info", opportunity: ctx.name } })).message;
