			frappe.show_alert({ message: __("Set a selling price first for: {0}", [r.unpriced.join(", ")]), indicator: "orange" }, 7);
			if (window.nx_actions.create_pl) return window.nx_actions.create_pl(ctx);
			return frappe.msgprint({ title: __("P&L not complete"), indicator: "orange",
				message: __("Set a selling price in the P&L for: {0}", [r.unpriced.join(", ")]) });
		}
		if (!r.full_count) {
			return frappe.msgprint({ title: __("No prices yet"), indicator: "orange",
				message: __("Add a selling price to the services in the P&L first, then make the proposal.") });
		}
		if (!r.active.length) {
			return frappe.confirm(__("Make a proposal with all {0} item(s), total {1}?", [r.full_count, money(r.full_total)]), () => make("full"));
		}
		if (!r.delta_count && !(r.reductions || []).length) {
			return frappe.msgprint({ title: __("No changes"), indicator: "blue",
				message: __("Nothing changed in the deal since {0}, so there is nothing to update.", [r.active.join(", ")]) });
		}
		const ok = r.delta_count > 0;
		const opt = (val, title, text, on) => `<label class="eye-pr-opt ${on ? "" : "disabled"}">
