				if (!mode) return frappe.show_alert({ message: __("Choose one of the two options"), indicator: "orange" });
				d.hide();
				make(mode);
			},
		});
		d.fields_dict.body.$wrapper.html(`<style>
				.eye-pr-opt{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--border-color);border-radius:10px;padding:12px 14px;margin-bottom:10px;cursor:pointer}
				.eye-pr-opt:hover{border-color:var(--primary)} .eye-pr-opt.disabled{opacity:.55;cursor:not-allowed}
				.eye-pr-opt input{margin-top:4px} .eye-pr-opt .t{font-weight:600;margin-bottom:2px} .eye-pr-opt .d{color:var(--text-muted)}
			</style>
			${opt("full", __("New proposal with all items"),
				__("{0} item(s), total {1}. The current proposal ({2}) will be marked Superseded.", [r.full_count, money(r.full_total), r.active.join(", ")]), true)}
			${opt("changes", __("Only the changes"), ok
				? __("{0} item(s) added or increased, total {1}. The current proposal stays as it is.", [r.delta_count, money(r.delta_total)])
				: __("Nothing was added or increased since the current proposal."), ok)}
			${r.reductions.length ? `<div class="text-muted small">${__("Reduced or removed: {0}. Reductions can't go in a changes-only proposal; use 'New proposal with all items' for them.", [esc(r.reductions.join(", "))])}</div>` : ""}`);
		d.show();
	};

	window.nx_actions.update_quotation = async (ctx) => {
