			if (window.nx_actions.create_pl) return window.nx_actions.create_pl(ctx);
			return frappe.msgprint({ title: __("P&L not complete"), indicator: "orange", message: __("Set a selling price in the P&L for: {0}", [r.unpriced.join(", ")]) });
		}
		if (!r.active.length) return window.nx_actions.create_quotation(ctx);
		const make = async (mode) => {
			const m = await frappe.call({ method: "eye.quote_update", args: { action: "make", opportunity: ctx.name, mode },
				freeze: true, freeze_message: __("Making the quotation...") });
			frappe.show_alert({ message: __("Quotation {0} is ready", [`<a href="/app/quotation/${encodeURIComponent(m.message)}">${esc(m.message)}</a>`]), indicator: "green" }, 8);
			if (ctx.refresh) ctx.refresh();
		};
		if (!r.delta_count && !(r.reductions || []).length) {
			return frappe.msgprint({ title: __("No changes"), indicator: "blue",
				message: __("Nothing changed in the deal since {0}, so there is nothing to update.", [r.active.join(", ")]) });
		}
		const can_full = !r.lock;
		const can_delta = r.delta_count > 0;
		const opt = (val, title, text, on, why) => `<label class="eye-pr-opt ${on ? "" : "disabled"}">
			<input type="radio" name="eye_q_mode" value="${val}" ${on ? "" : "disabled"}>
			<div><div class="t">${title}</div><div class="d">${text}</div>${!on && why ? `<div class="w">${why}</div>` : ""}</div></label>`;
		const d = new frappe.ui.Dialog({
