				depends_on: df.depends_on, mandatory_depends_on: df.mandatory_depends_on, reqd: df.reqd,
				description: df.description,
				default: df.fieldname === "custom_po_status" ? status : frm.doc[df.fieldname],
			})),
			primary_action_label: __("Save"),
			async primary_action(v) {
				for (const df of F) await frm.set_value(df.fieldname, v[df.fieldname] === undefined ? null : v[df.fieldname]);
				await frm.save();
				d.hide();
			},
		});
		d.show();
	};
	const eye_po_part = (frm, pos) => {
		if (!pos || !pos.length || !frm.fields_dict.custom_po_status) return "";
		$("#eye-po-css").remove();
		$(`<style id="eye-po-css">
			.eye-po-track { display: flex; gap: 3px; width: 100%; margin-top: 2px; }
			.eye-po-seg { flex: 1; min-width: 0; height: 32px; padding: 0 16px; display: flex; align-items: center; justify-content: center;
				font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; user-select: none;
				background: var(--control-bg, rgba(128,128,128,.12)); color: var(--text-muted);
				clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
				transition: filter .12s, background .12s, color .12s; }
			.eye-po-seg:first-child { clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%); border-radius: 8px 0 0 8px; }
			.eye-po-seg:last-child { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%, 12px 50%); border-radius: 0 8px 8px 0; }
			.eye-po-seg:only-child { clip-path: none; border-radius: 8px; }
			.eye-po-seg.done { background: rgba(99,102,241,.16); color: var(--text-color); }
			.eye-po-seg.on { background: #6366f1; color: #fff; font-weight: 600; }
			.eye-po-seg:hover { filter: brightness(1.18); color: var(--text-color); }
			.eye-po-seg.on:hover { color: #fff; }
		</style>`).appendTo(document.head);
		const cur = frm.doc.custom_po_status;
		const ci = pos.indexOf(cur);
		const segs = pos.map((s, i) => {
			const cls = i === ci ? "on" : ci >= 0 && i < ci ? "done" : "";
			const tip = i === ci ? __("Edit the PO details") : __("Set PO status to {0}", [__(s)]);
			return `<div role="button" tabindex="0" class="eye-po-seg ${cls}" data-po="${esc(s)}" title="${esc(tip)}">${cls === "done" ? "✓ " : ""}${esc(__(s))}</div>`;
		}).join("");
		const bits = [];
		if (frm.doc.custom_po_no) bits.push(esc(frm.doc.custom_po_no));
		if (frm.doc.custom_expected_po_date) bits.push(__("expected {0}", [frappe.datetime.str_to_user(frm.doc.custom_expected_po_date)]));
		return `<div style="grid-column:1 / -1;padding:10px 0 0 0;border-left:0;border-top:1px solid var(--border-color);margin-top:10px">
			<div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px">
				<div class="k">${__("Purchase Order")}</div>
				${bits.length ? `<span class="text-muted" style="font-size:12px">${bits.join(" · ")}</span>` : ""}</div>
			<div class="eye-po-track">${segs}</div></div>`;
	};

	async function load(frm) {
		const since = frm.doc.creation;
		const [quotes, brs, so] = await Promise.all([
			frappe.db.get_list("Quotation", { filters: { opportunity: frm.doc.name, docstatus: ["<", 2], creation: [">=", since] },
				fields: ["name", "docstatus", "grand_total", "currency"], order_by: "creation desc", limit: 1 }),
			frappe.db.get_list("Billing Request", { filters: { opportunity: frm.doc.name, creation: [">=", since] },
				fields: ["billing_stage", "total", "collected_amount", "invoice_number"], limit: 500 }),
			frm.doc.custom_sales_order
				? frappe.db.get_value("Sales Order", frm.doc.custom_sales_order, ["total", "grand_total"]).then((r) => r.message || {})
				: Promise.resolve(null),
		]);
		return { q: quotes[0], brs, so };
	}

	function build(frm, { q, brs, so }) {
		const d = frm.doc;
		const cur = d.currency;

		// deal
		let close = "";
		if (d.expected_closing) {
			const days = frappe.datetime.get_day_diff(d.expected_closing, frappe.datetime.get_today());
			close = days < 0 ? `<span class="late">${__("Closing date passed {0} days ago", [-days])}</span>`
				: days === 0 ? __("Closes today") : __("Closes in {0} days", [days]);
		}
		const deal = `<div><div class="k">${__("Deal")}</div>
			<div class="v">${pill(__(d.sales_stage || "-"), "blue")}</div>
			<div class="s">${close}${close ? "<br>" : ""}${__("Updated {0}", [frappe.datetime.prettyDate(d.modified)])}</div></div>`;

		// pricing
		const ps = d.custom_pricing_status;
		const pricing = `<div><div class="k">${__("Pricing")}</div>
			<div class="v">${ps ? pill(__(ps), layout_colors("custom_pricing_status")[ps]) : `<span class="text-muted">${__("Not sent yet")}</span>`}</div>
			<div class="s">${flt(d.custom_total_cost) ? `${__("Cost")} ${short(d.custom_total_cost, cur)} · ${__("Min")} ${short(d.custom_total_selling, cur)}` : ""}</div></div>`;

		// quotation
		const quotation = q
			? `<div><div class="k">${__("Quotation")}</div>
				<div class="v"><a data-open-q="${esc(q.name)}">${esc(q.name)}</a>${pill(q.docstatus === 1 ? __("Submitted") : __("Draft"), q.docstatus === 1 ? "green" : "gray")}<button class="btn btn-xs pdf" data-pdf="${esc(q.name)}">${frappe.utils.icon("download", "xs")} PDF</button></div></div>`
			: `<div><div class="k">${__("Quotation")}</div><div class="v"><span class="text-muted">${__("Not made yet")}</span></div></div>`;

		// invoicing
		const so_total = so ? flt(so.total || so.grand_total) : 0;
		const requested = brs.reduce((s, r) => s + flt(r.total), 0);
		const invoiced = brs.filter((r) => r.invoice_number).reduce((s, r) => s + flt(r.total), 0);
		const collected = brs.reduce((s, r) => s + flt(r.collected_amount), 0);
		const counts = {};
		brs.forEach((r) => (counts[r.billing_stage] = (counts[r.billing_stage] || 0) + 1));
		const seg = (v, color) => `<i style="width:${Math.max(0, Math.min(pct(v, so_total), 100))}%;background:${color}"></i>`;
		const invoicing = so
			? `<div data-go-inv style="cursor:pointer" title="${__("Go to the invoices")}"><div class="k">${__("Invoicing")}</div>
				<div class="v">${pct(invoiced, so_total)}% <span class="text-muted" style="font-weight:normal">${__("invoiced")}</span>
					· ${pct(collected, so_total)}% <span class="text-muted" style="font-weight:normal">${__("collected")}</span></div>
				<div class="bar">${seg(collected, "var(--green-500, #2f9e44)")}${seg(invoiced - collected, "var(--blue-500, #2490ef)")}${seg(requested - invoiced, "var(--gray-400, #a0a8b1)")}</div>
				<div class="s">${short(requested, cur)} ${__("requested of")} ${short(so_total, cur)}${Object.keys(counts).length ? "<br>" : ""}
					${Object.entries(counts).map(([st, n]) => `${n} ${esc(__(st))}`).join(" · ")}</div></div>`
			: `<div data-go-inv style="cursor:pointer" title="${__("Go to the invoices")}"><div class="k">${__("Invoicing")}</div><div class="v"><span class="text-muted">${__("No Sales Order yet")}</span></div></div>`;

		return pricing + (frm.__eye_prop_seg || "") + quotation + invoicing + eye_po_part(frm, arguments[1].pos);
	}

	async function render(frm) {
		const $page = $(frm.page.wrapper);
		if (frm.is_new()) return $page.find(".eye-sum").remove();
		const token = (frm.__eye_sum = (frm.__eye_sum || 0) + 1);
		const data = await load(frm);
		data.pos = await eye_po_statuses();
		if (token !== frm.__eye_sum) return;
		const html = build(frm, data);
		let $box = $page.find(".eye-sum");
		if (!$box.length) {
			const $lab = $page.find("div, span, label")
				.filter((_, el) => !el.children.length && (el.textContent || "").trim() === __("Series")).first();
			$box = $('<div class="eye-sum"></div>');
			const $dbar = $page.find(".eye-deal-bar").first();
			if ($dbar.length) $dbar.append($box);
			else if ($lab.length) $lab.parent().parent().after($box);
			else $(frm.layout.wrapper).prepend($box);
		}
		if ($box.data("html") === html) return;
		$box.html(html).data("html", html);
		eye_pl_box(frm, $box); eye_sum_tidy($box); eye_sum_sub($box);
		const acc = (window.eye_crm && window.eye_crm.ACCOUNTS_STAGE) || "Finance, please approve";
		if (frm.doc.sales_stage === acc && eye_can_approve()) {
			const $row = $('<div style="display:flex;gap:6px;margin-top:8px;align-items:center;flex-wrap:wrap"><span style="font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted);margin-right:4px">Finance approval</span></div>');
                        setTimeout(() => { const $inv = $box.children().eq(3); if ($inv.length) $inv.append($row); }, 0);
			const $ok = $('<button class="btn btn-xs"></button>').text(__("Approve"))
				.on("click", () => eye_approve(frm.doc.name, () => frm.reload_doc()));
			["background", "border-color"].forEach((p) => $ok[0].style.setProperty(p, "var(--blue-500, #2490ef)", "important"));
			$ok[0].style.setProperty("color", "#fff", "important");
			$ok[0].style.setProperty("font-weight", "600", "important");
			const $no = $('<button class="btn btn-xs btn-default"></button>').text(__("Reject"))
				.on("click", () => eye_reject(frm.doc.name, () => frm.reload_doc()));
			$row.append($ok, $no).appendTo($box.children().first());
		}
		$box.find("[data-open-q]").on("click", function () { frappe.set_route("Form", "Quotation", this.dataset.openQ); });
		$box.find("[data-go-inv]").on("click", (e) => {
			if ($(e.target).closest("button").length) return;
			frm.scroll_to_field("custom_invoices_html");
		});
		$box.find(".eye-po-seg, .eye-po-col").on("click keydown", function (e) {
			if (e.type === "keydown" && e.key !== "Enter" && e.key !== " ") return;
			eye_po_dialog(frm, this.dataset.po);
		});
		const $pdf = $box.find("[data-pdf]");
		$pdf.each((_, b) => {
			b.style.setProperty("background", "var(--blue-500, #2490ef)", "important");
			b.style.setProperty("border-color", "var(--blue-500, #2490ef)", "important");
			b.style.setProperty("color", "#fff", "important");
			b.style.setProperty("font-weight", "600", "important");
		});
		$pdf.on("click", function () {
			window.open("/api/method/frappe.utils.print_format.download_pdf?doctype=Quotation&name="
				+ encodeURIComponent(this.dataset.pdf) + "&format=" + encodeURIComponent(FMT) + "&no_letterhead=0");
		});
	}

	const run = (frm) => [80, 900].forEach((ms) => setTimeout(() => render(frm), ms));
	frappe.ui.form.on("Opportunity", { refresh: run, after_save: run });
})();

(() => {
	const head_slot = ($anchor) => {
		const $head = $anchor.closest(".form-section").find(".section-head").first();
		if (!$head.length) return null;
		$head.css({ display: "flex", alignItems: "center" });
		let $slot = $head.children(".eye-head-btn");
		if (!$slot.length) $slot = $('<div class="eye-head-btn" style="margin-left:auto;display:flex;align-items:center;gap:8px"></div>').appendTo($head);
		return $slot;
	};
	const blue = (b) => {
		b.style.setProperty("background", "var(--blue-500, #2490ef)", "important");
		b.style.setProperty("border-color", "var(--blue-500, #2490ef)", "important");
		b.style.setProperty("color", "#fff", "important");
		b.style.setProperty("font-weight", "600", "important");
	};
	const THEME = { "To be invoiced": "gray", "Finance, please issue": "orange", "Invoiced": "blue", "Collected": "green" };
	const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));

	const place = (frm) => {
		const f = frm.fields_dict.opportunity;
		if (!f || !f.$wrapper || frm.is_new()) return;
		const $slot = head_slot(f.$wrapper);
		if (!$slot) return;
		$slot.empty();
		const E = window.eye_crm || {};
		const d = frm.doc;
		const after = () => frm.reload_doc();
		const fin = E.is_finance ? E.is_finance() : frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
		const pill = (text, theme) =>
			$(`<span class="indicator-pill no-indicator-dot ${theme}" style="font-weight:600"></span>`).text(text).appendTo($slot);
		const btn = (label, fn) => {
			const b = $('<button class="btn btn-sm"></button>').text(label)
				.on("click", (e) => { e.stopPropagation(); fn(); }).appendTo($slot);
			blue(b[0]);
		};
		if (d.billing_stage === "To be invoiced") {
			btn(__("Send to Finance"), () => {
				if (frm.is_dirty()) return frappe.msgprint(__("Save first."));
				frm.set_value("billing_stage", "Finance, please issue");
				frm.save();
			});
		} else if (d.billing_stage === "Finance, please issue") {
			pill(__("With Finance"), "orange");
			if (fin && E.invoiced_dialog) btn(__("Invoice Issued"), () => E.invoiced_dialog(d.name, after));
		} else if (d.billing_stage === "Invoiced") {
			pill(d.invoice_number ? __("Invoiced · {0}", [d.invoice_number]) : __("Invoiced"), "blue");
			if (fin && E.collected_dialog) btn(__("Payment Received"), () => E.collected_dialog(d.name, after));
		} else if (d.billing_stage === "Collected") {
			pill(__("Collected"), "green");
		}
		$(frm.page.wrapper).find(".page-actions button, .page-actions .btn").each((_, b) => {
			if ((b.textContent || "").trim() === __("Send to Finance")) blue(b);
		});
	};
	const run = (frm) => [0, 300, 1000].forEach((ms) => setTimeout(() => place(frm), ms));
	frappe.ui.form.on("Billing Request", { refresh: run });
})();

(() => {
