				${fact(__("Expected"), date(doc.expected_date))}
				${fact(__("Invoice"), doc.invoice_number ? `${esc(doc.invoice_number)} <span class="text-muted" style="font-weight:normal">· ${date(doc.invoice_date)}</span>` : "—")}
				${fact(__("Total"), money(doc.total))}
