		let action = null;
		if (doc.billing_stage === "To be invoiced") {
			action = [__("Send to Finance"), () => frappe.xcall("frappe.client.set_value",
				{ doctype: "Billing Request", name, fieldname: "billing_stage", value: "Finance, please issue" }).then(done)];
		} else if (fin && doc.billing_stage === "Finance, please issue" && E.invoiced_dialog) {
			action = [__("Invoice Issued"), () => E.invoiced_dialog(name, done)];
		} else if (fin && doc.billing_stage === "Invoiced" && E.collected_dialog) {
			action = [__("Payment Received"), () => E.collected_dialog(name, done)];
		}
		const dlg = new frappe.ui.Dialog({
			title: name,
			size: "large",
			fields: [{ fieldtype: "HTML", fieldname: "body" }],
			secondary_action_label: __("Open full page"),
			secondary_action: () => { dlg.hide(); frappe.set_route("Form", "Billing Request", name); },
			...(action ? { primary_action_label: action[0], primary_action: action[1] } : {}),
		});
		dlg.fields_dict.body.$wrapper.html(body);
		dlg.show();
	};
	const render = async (frm) => {
		const f = frm.fields_dict.custom_invoices_html;
		if (!f) return;
		const $sec = f.$wrapper.closest(".form-section");
		if (frm.is_new()) return $sec.hide();
		$sec.show();
		const $slot = head_slot(f.$wrapper);
		const { rows, so_total } = await load(frm);
		const cur = frm.doc.currency;
		const money = (v) => format_currency(flt(v), cur);
		const requested = rows.reduce((s, r) => s + flt(r.total), 0);
		const invoiced = rows.filter((r) => DONE.includes(r.billing_stage)).reduce((s, r) => s + flt(r.total), 0);
		const collected = rows.reduce((s, r) => s + flt(r.collected_amount), 0);

		if ($slot) {
			$slot.children(".eye-inv").remove();
			$('<button class="btn btn-default btn-sm eye-inv"></button>').text(__("View all"))
				.on("click", (e) => { e.stopPropagation(); frappe.set_route("List", "Billing Request", { opportunity: frm.doc.name }); })
				.appendTo($slot);
			if (frm.doc.sales_stage === APPROVED && frm.doc.custom_sales_order) {
				const b = $('<button class="btn btn-sm eye-inv"></button>').text(__("Request Invoice"))
					.on("click", (e) => {
						e.stopPropagation();
						if (frm.is_dirty()) return frappe.msgprint(__("Save the Opportunity first."));
						const E = window.eye_crm;
						if (!E || !E.request_invoice_dialog) return frappe.msgprint(__("Reload the page and try again."));
						E.request_invoice_dialog(frm.doc.name, () => frm.reload_doc());
					})
					.appendTo($slot);
				blue(b[0]);
			} else {
				$('<span class="indicator-pill no-indicator-dot gray eye-inv" style="font-weight:600"></span>')
					.text(__("After Accounts approve")).appendTo($slot);
			}
		}

		frm.remove_custom_button(__("Request Invoice"));

		const tones = { req: "var(--gray-500, #8d99a6)", inv: "var(--blue-500, #2490ef)", col: "var(--green-500, #2f9e44)" };
		let html = "";
		if (so_total > 0 || rows.length) {
			html += `<div class="eye-inv-tiles">
				${tile(__("Sales Order"), money(so_total), frm.doc.custom_sales_order ? esc(frm.doc.custom_sales_order) : __("not made yet"), null)}
				${tile(__("Requested"), money(requested), __("{0}% of the Sales Order", [pct(requested, so_total)]), pct(requested, so_total), tones.req)}
				${tile(__("Invoiced"), money(invoiced), __("{0}% of the Sales Order", [pct(invoiced, so_total)]), pct(invoiced, so_total), tones.inv)}
				${tile(__("Collected"), money(collected), __("{0}% of what is invoiced", [pct(collected, invoiced)]), pct(collected, invoiced), tones.col)}
			</div>`;
		}
		if (!rows.length) {
			html += `<div class="eye-inv-empty">${frm.doc.custom_sales_order ? __("No invoice requests yet. Press Request Invoice to bill part or all of the Sales Order.")
				: __("Invoices are requested from the Sales Order, which is made when Accounts approve the project.")}</div>`;
		} else {
			html += `<table class="eye-inv-table"><thead><tr>
				<th>${__("Request")}</th><th>${__("Stage")}</th><th>${__("Invoice / Expected")}</th>
				<th class="num">${__("Amount")}</th><th class="num">${__("Collected")}</th></tr></thead><tbody>
				${rows.map((r) => `<tr class="r" data-name="${esc(r.name)}">
					<td><b>${esc(r.name)}</b></td>
					<td><span class="indicator-pill no-indicator-dot ${THEME[r.billing_stage] || "gray"}">${esc(__(r.billing_stage))}</span></td>
					<td>${r.invoice_number ? `${esc(r.invoice_number)} <span class="text-muted">· ${frappe.datetime.str_to_user(r.invoice_date)}</span>`
						: r.expected_date ? `<span class="text-muted">${__("expected")}</span> ${frappe.datetime.str_to_user(r.expected_date)}` : ""}</td>
					<td class="num">${money(r.total)}</td>
					<td class="num">${flt(r.collected_amount) ? money(r.collected_amount) : '<span class="text-muted">—</span>'}</td>
				</tr>`).join("")}
				</tbody></table>`;
		}
		f.$wrapper.html(html);
		f.$wrapper.find("tr.r").on("click", function () {
			peek(frm, this.dataset.name);
		});
		info_item(frm, so_total > 0 ? pct(invoiced, so_total) : null, pct(collected, invoiced));
	};
	const run = (frm) => [0, 400, 1200].forEach((ms) => setTimeout(() => render(frm), ms));
	frappe.ui.form.on("Opportunity", { refresh: run });
})();

