(() => {
	const FMT = "Eye Quotation";
	const head_slot = (f) => {
		const $head = f.$wrapper.closest(".form-section").find(".section-head").first();
		if (!$head.length) return null;
		$head.css({ display: "flex", alignItems: "center" });
		let $slot = $head.children(".eye-head-btn");
		if (!$slot.length) $slot = $('<div class="eye-head-btn" style="margin-left:auto;display:flex;align-items:center;gap:8px"></div>').appendTo($head);
		return $slot;
	};
	const blue = (b) => {
		b.style.setProperty("background", "var(--blue-500, #2490ef)", "important");
		b.style.setProperty("border-color", "var(--blue-500, #2490ef)", "important");
		b.style.setProperty("color", "#fff", "important");
		b.style.setProperty("font-weight", "600", "important");
	};
	const latest = (frm) => frappe.db.get_list("Quotation", {
		filters: { opportunity: frm.doc.name, docstatus: ["<", 2], creation: [">=", frm.doc.creation] },
		fields: ["name", "docstatus", "grand_total", "currency", "valid_till"],
		order_by: "creation desc", limit: 1,
	}).then((r) => r[0]);
	const make = (frm) => {
		if (frm.is_dirty()) {
			frappe.msgprint(__("Save the Opportunity first."));
			return;
		}
		const ctx = { doctype: "Opportunity", name: frm.doc.name, frm, refresh: () => frm.reload_doc() };
		if (window.nx_actions && window.nx_actions.create_quotation) return window.nx_actions.update_quotation(ctx);
		frappe.call({ method: "eye.quote", args: { name: frm.doc.name }, freeze: true }).then(() => frm.reload_doc());
	};
	const download = (q) => window.open("/api/method/frappe.utils.print_format.download_pdf?doctype=Quotation&name="
		+ encodeURIComponent(q) + "&format=" + encodeURIComponent(FMT) + "&no_letterhead=0");
	const top_bar = (frm, q) => { $(frm.page.wrapper).find(".eye-quote-head, .eye-q-item, .eye-q-panel").remove(); return;
		const $page = $(frm.page.wrapper);
		$page.find(".eye-quote-head, .eye-q-item, .eye-q-panel").remove();
		frm.remove_custom_button(__("Download Quotation"));
		if (!q) return;
		const $lab = $page.find("div, span, label")
			.filter((_, el) => !el.children.length && (el.textContent || "").trim() === __("Series")).first();
		if (!$lab.length) return;
		const $row = $lab.parent().parent();
		$row.css({ display: "flex", flexWrap: "wrap", alignItems: "flex-end", columnGap: "36px", rowGap: "12px", width: "100%" });

		const $c = $row.children().first().clone(false).addClass("eye-q-item");
		const kids = $c.children();
		if (kids.length < 2) return;
		$c.css({ marginLeft: "auto", paddingLeft: "24px", borderLeft: "1px solid var(--border-color)" });

		const sub = q.docstatus === 1;
		const pdf = $('<button class="btn btn-xs"></button>')
			.html(`${frappe.utils.icon("download", "xs")} ${__("PDF")}`)
			.on("click", (e) => { e.stopPropagation(); download(q.name); });
		["background", "border-color"].forEach((p) => pdf[0].style.setProperty(p, "var(--blue-500, #2490ef)", "important"));
		pdf[0].style.setProperty("color", "#fff", "important");
		pdf[0].style.setProperty("font-weight", "600", "important");

		kids.eq(0).text(__("Quotation"));
		kids.eq(1).empty().css({ display: "flex", alignItems: "center", gap: "10px", whiteSpace: "nowrap" }).append(
			$('<a style="cursor:pointer;color:inherit"></a>').text(q.name)
				.on("click", () => frappe.set_route("Form", "Quotation", q.name)),
			$(`<span class="indicator-pill no-indicator-dot ${sub ? "green" : "gray"}"></span>`)
				.text(sub ? __("Submitted") : __("Draft")),
			$('<span></span>').text(format_currency(q.grand_total, q.currency))
				.attr("title", q.valid_till ? __("Valid till {0}", [frappe.datetime.str_to_user(q.valid_till)]) : ""),
			pdf
		);
		$row.append($c);
	};
	const render = (frm) => {
		const f = frm.fields_dict.custom_create_quotation;
		if (!f || !f.$input) return;
		if (frm.is_new()) { f.$wrapper.closest(".form-section").hide(); top_bar(frm, null); return; }
		f.$wrapper.closest(".form-section").show();
		const $slot = head_slot(f);
		if (!$slot) return;
		if (!$slot.find(f.$input).length) $slot.append(f.$input);
		f.$input.removeClass("btn-xs").addClass("btn-sm").css({ margin: 0 });
		f.$input.off("click.eyehead").on("click.eyehead", (e) => e.stopPropagation());
		f.$wrapper.hide();
		blue(f.$input[0]);
		latest(frm).then((q) => {
			top_bar(frm, q);
			f.$input.text(q && q.docstatus === 0 ? __("Update Quotation") : __("Create Quotation"));
			f.$input.toggle(!frm.doc.custom_sales_order);
			$slot.children(".eye-quote-pill, .eye-quote-dl").remove();
			const $html = frm.fields_dict.custom_quote_html && frm.fields_dict.custom_quote_html.$wrapper;
			if (!q) {
				if ($html) $html.html(`<div class="text-muted small">${__("No quotation yet")}</div>`);
				return;
			}
			const state = q.docstatus === 1 ? __("Submitted") : __("Draft");
			$(`<a class="eye-quote-pill indicator-pill no-indicator-dot ${q.docstatus === 1 ? "green" : "gray"}" style="font-weight:600;cursor:pointer"></a>`)
				.text(q.name)
				.on("click", (e) => { e.stopPropagation(); frappe.set_route("Form", "Quotation", q.name); })
				.prependTo($slot);
			$(`<button class="eye-quote-dl btn btn-default btn-sm"></button>`)
				.text(__("Download PDF"))
				.on("click", (e) => { e.stopPropagation(); download(q.name); })
				.insertBefore(f.$input);
			if ($html) $html.html(`<div class="small">
				<b>${frappe.utils.escape_html(q.name)}</b> · ${state}
				· ${format_currency(q.grand_total, q.currency)}
				${q.valid_till ? " · " + __("valid till {0}", [frappe.datetime.str_to_user(q.valid_till)]) : ""}</div>`);
		});
	};
	const swap_create_menu = (frm) => {
		frm.remove_custom_button(__("Quotation"), __("Create"));
		if (frm.is_new() || frm.doc.custom_sales_order) return;
		$();
	};
	const run = (frm) => [0, 300, 1000].forEach((ms) => setTimeout(() => { swap_create_menu(frm); render(frm); }, ms));
	frappe.ui.form.on("Opportunity", {
		refresh: run,
		onload_post_render: run,
		custom_create_quotation: (frm) => make(frm),
	});
})();

