				E.api("reject_project", { name, reason: v.reason }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Sent back to Deals in Hand"), indicator: "orange" });
					after && after();
				}),
			__("Send back to Sales"),
			__("Send Back")
		);
	E.retry_sales_order = (name, after) =>
		E.api("make_sales_order", { name }, { freeze: true }).then((so) => {
			frappe.show_alert({ message: __("Sales Order {0}", [so]), indicator: "green" });
			after && after();
		});

	// ---- invoices
	E.request_invoice_dialog = async (opportunity, after) => {
		const so = await E.billing("so_lines", { opportunity });
		const cur = so.currency;
		const rows = so.rows
			.filter((r) => r.left > 0.000001 && flt(r.rate) > 0)
			.map((r) => {
				const left_amount = flt(r.left * r.rate, 2);
				return { so_detail: r.so_detail, item_code: r.item_code, item_name: r.item_name, rate: r.rate,
					left_amount, amount: left_amount, total_amount: flt(r.qty * r.rate, 2), billed_amount: flt((r.qty - r.left) * r.rate, 2) };
			});
		if (!rows.length) return frappe.msgprint(__("Everything on Sales Order {0} is already requested.", [so.sales_order]));
		const starts = await frappe.db.get_list("Billing Stage", { filters: { custom_can_start_here: 1 },
			fields: ["name", "custom_start_default"], order_by: "creation asc", limit: 50 });
		const d = new frappe.ui.Dialog({
			title: __("Request an invoice"),
			size: "extra-large",
			fields: [
				{ fieldtype: "Select", fieldname: "stage", label: __("Stage"), reqd: 1,
					options: starts.map((x) => x.name),
					default: (starts.find((x) => x.custom_start_default) || starts[0] || {}).name,
					hidden: starts.length < 2 ? 1 : 0 },
				{ fieldtype: "Date", fieldname: "expected_date", label: __("Expected invoice date"), reqd: 1,
					default: frappe.datetime.get_today() },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Finance") },
				{ fieldtype: "Section Break", label: __("Items from {0}", [so.sales_order]) },
				{ fieldtype: "Percent", fieldname: "pct", label: __("% of what's left"),
					description: __("Fills every line; then change any amount by hand"),
					onchange() {
						const p = flt(d.get_value("pct"));
						d.fields_dict.lines.df.data.forEach((r) => (r.amount = flt((r.left_amount * p) / 100, 2)));
						d.fields_dict.lines.grid.refresh();
					} },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Section Break" },
				{ fieldtype: "Table", fieldname: "lines", label: __("Lines"), cannot_add_rows: 1, in_place_edit: 1, data: rows,
					fields: [
						{ fieldtype: "Data", fieldname: "so_detail", hidden: 1 },
						{ fieldtype: "Float", fieldname: "rate", hidden: 1 },
						{ fieldtype: "Link", fieldname: "item_code", label: __("Item"), options: "Item", read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "total_amount", label: __("Line total"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
					{ fieldtype: "Currency", fieldname: "billed_amount", label: __("Already billed"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
						{ fieldtype: "Currency", fieldname: "left_amount", label: __("Left to bill"), options: cur, read_only: 1, in_list_view: 1, columns: 2 },
						{ fieldtype: "Currency", fieldname: "amount", label: __("Amount to bill"), options: cur, in_list_view: 1, columns: 2 },
					] },
			],
			primary_action_label: __("Request"),
			primary_action(v) {
				const lines = (d.fields_dict.lines.df.data || []).filter((r) => flt(r.amount) > 0);
				if (!lines.length) return frappe.msgprint(__("Enter the amount to bill on at least one line."));
				const over = lines.filter((r) => flt(r.amount) > flt(r.left_amount) + 0.005);
				if (over.length) {
					return frappe.msgprint(over.map((r) => __("{0}: only {1} is left to bill",
						[E.esc(r.item_code), E.money(r.left_amount, cur)])).join("<br>"));
				}
				const total = lines.reduce((s, r) => s + flt(r.amount), 0);
				const payload = lines.map((r) => ({ so_detail: r.so_detail, qty: Math.round((flt(r.amount) / flt(r.rate)) * 1e9) / 1e9 }));
				E.billing("create", { opportunity, rows: JSON.stringify(payload), expected_date: v.expected_date,
					notes: v.notes, stage: v.stage }, { freeze: true })
					.then((name) => {
						d.hide();
						frappe.show_alert({ message: __("Invoice request {0} for {1}", [name, E.money(total, cur)]), indicator: "green" });
						after && after();
					});
			},
		});
		d.show();
	};
	E.invoiced_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Data", fieldname: "invoice_number", label: __("Invoice number"), reqd: 1 },
				{ fieldtype: "Date", fieldname: "invoice_date", label: __("Invoice date"), reqd: 1, default: frappe.datetime.get_today() },
			],
			(v) =>
				E.billing("mark_invoiced", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Invoiced"), indicator: "green" });
					after && after();
				}),
			__("Invoice issued"),
			__("Save")
		);
	E.collected_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Date", fieldname: "collected_on", label: __("Collected on"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Currency", fieldname: "amount", label: __("Amount (empty: the full invoice)") },
			],
			(v) =>
				E.billing("mark_collected", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Collected"), indicator: "green" });
					after && after();
				}),
			__("Payment received"),
			__("Save")
		);

	// ---- card badges (Kanban v2)
	E.badge_row = (badges) => {
		const row = document.createElement("div");
		row.className = "flex flex-wrap items-center gap-1 mt-2";
		badges.filter((b) => b && b.label).forEach((b) => {
			const el = frappe.ui.badge({ label: b.label, theme: b.theme || "gray", variant: b.variant, size: "sm" })[0];
			if (b.tooltip) frappe.ui.tooltip(el, { text: b.tooltip });
			row.appendChild(el);
		});
		return row;
	};
	E.board_field = (() => {
		const cache = {};
		return (board) => {
			if (!board) return Promise.resolve(null);
			cache[board] = cache[board] || frappe.db.get_value("Kanban Board", board, "field_name").then((r) => r.message?.field_name);
			return cache[board];
		};
	})();

	// the PL is drawn on the server (eye.pricing pl_view), so the form shows the same screen
	E.pl_dialog = async function (name) {
		const r = await E.api("pl_view", { name });
